class Fail extends Error {}
const fail = (m) => { throw new Fail(m) }

const newTable = () => ({ t: 'table', m: new Map(), hdr: false })
const isWs = (c) => c === ' ' || c === '\t'
const bareChar = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)

function parseLine(s, st) {
  let i = 0
  const skip = () => { while (i < s.length && isWs(s[i])) i++ }
  const atEnd = () => { skip(); return i >= s.length || s[i] === '#' || s[i] === ';' }

  function quoted(q) {
    i++
    let out = ''
    for (;;) {
      if (i >= s.length) fail('unterminated string')
      const c = s[i]
      if (c === q) { i++; return out }
      if (c === '\\' && q === '"') {
        i++
        if (i >= s.length) fail('unterminated string')
        const e = s[i]
        const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (Object.hasOwn(map, e)) { out += map[e]; i++ }
        else if (e === 'u') {
          const h = s.slice(i + 1, i + 5)
          if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16)); i += 5
        } else fail('invalid escape \\' + String.fromCodePoint(s.codePointAt(i)))
      } else { out += c; i++ }
    }
  }

  function name() {
    const c = s[i]
    if (c === '"' || c === "'") return quoted(c)
    if (!bareChar(c)) fail('expected a name')
    const st0 = i
    while (bareChar(s[i])) i++
    return s.slice(st0, i)
  }

  function dotted() {
    const names = []
    for (;;) {
      skip()
      names.push(name())
      skip()
      if (s[i] === '.') i++
      else return names
    }
  }

  function descend(cur, seg, path) {
    const n = cur.m.get(seg)
    if (n === undefined) { const t = newTable(); cur.m.set(seg, t); return t }
    if (n.t === 'table') return n
    if (n.t === 'array' && n.aot) return n.items[n.items.length - 1]
    return fail(path + ' is not a table')
  }

  // assign value at dotted names inside table `cur`; base is path of cur
  function assign(cur, base, names, val) {
    let p = base
    for (let k = 0; k < names.length - 1; k++) {
      p = p.concat(names[k])
      cur = descend(cur, names[k], p.join('.'))
    }
    const last = names[names.length - 1]
    if (cur.m.has(last)) fail('key ' + base.concat(names).join('.') + ' is defined twice')
    cur.m.set(last, val)
  }

  function value(base) {
    skip()
    if (i >= s.length || s[i] === '#' || s[i] === ';' || s[i] === ',' || s[i] === ']' || s[i] === '}') fail('expected a value')
    const c = s[i]
    if (c === '"' || c === "'") return { t: 'string', v: quoted(c) }
    if (c === '[') {
      i++
      const arr = { t: 'array', items: [], aot: false }
      for (;;) {
        if (atEnd()) fail('unterminated array')
        if (s[i] === ']') { i++; return arr }
        arr.items.push(value(base.concat('[]')))
        if (atEnd()) fail('unterminated array')
        if (s[i] === ',') { i++; continue }
        if (s[i] === ']') { i++; return arr }
        fail('unterminated array')
      }
    }
    if (c === '{') {
      i++
      const tbl = newTable()
      if (atEnd()) fail('unterminated inline table')
      if (s[i] === '}') { i++; return tbl }
      for (;;) {
        if (atEnd()) fail('unterminated inline table')
        const names = dotted()
        if (s[i] !== '=') fail('expected = in an inline table')
        i++
        const v = value(base)
        assign(tbl, base, names, v)
        if (atEnd()) fail('unterminated inline table')
        if (s[i] === ',') { i++; continue }
        if (s[i] === '}') { i++; return tbl }
        fail('unterminated inline table')
      }
    }
    const st0 = i
    while (i < s.length && !isWs(s[i]) && s[i] !== ',' && s[i] !== ']' && s[i] !== '}') i++
    const tok = s.slice(st0, i)
    if (tok === 'true' || tok === 'false') return { t: 'boolean', v: tok === 'true' }
    const int = '[+-]?\\d+(?:_\\d+)*'
    if (new RegExp('^' + int + '$').test(tok)) return { t: 'integer', v: Number(tok.replaceAll('_', '')) }
    const fl = new RegExp('^' + int + '(?:\\.\\d+(?:_\\d+)*(?:[eE][+-]?\\d+(?:_\\d+)*)?|[eE][+-]?\\d+(?:_\\d+)*)$')
    if (fl.test(tok)) return { t: 'float', v: Number(tok.replaceAll('_', '')) }
    return fail('invalid value ' + tok)
  }

