  if (i >= s.length || s[i] === '#' || s[i] === ';') return
  if (s[i] === '[') {
    const aot = s[i + 1] === '['
    i += aot ? 2 : 1
    const names = dotted()
    if (s[i] !== ']') fail('unterminated table header')
    i++
    if (aot) {
      if (s[i] !== ']') fail('unterminated table header')
      i++
    }
    if (!atEnd()) fail('trailing text after a table header')
    let cur = st.root
    let p = []
    for (let k = 0; k < names.length - 1; k++) {
      p.push(names[k])
      cur = descend(cur, names[k], p.join('.'))
    }
    const last = names[names.length - 1]
    const full = names.join('.')
    const n = cur.m.get(last)
    if (aot) {
      if (n === undefined) {
        const a = { t: 'array', items: [], aot: true }
        cur.m.set(last, a)
        st.cur = newTable(); a.items.push(st.cur)
      } else if (n.t === 'array' && n.aot) {
        st.cur = newTable(); n.items.push(st.cur)
      } else fail(full + ' is not an array of tables')
    } else if (n === undefined) {
      const t = newTable(); t.hdr = true
      cur.m.set(last, t); st.cur = t
    } else if (n.t !== 'table') fail(full + ' is not a table')
    else {
      if (n.hdr) fail('table ' + full + ' is defined twice')
      n.hdr = true; st.cur = n
    }
    st.path = names.slice()
    st.path = p.concat(last)
    return
  }
  const names = dotted()
  if (s[i] !== '=') fail('expected key = value')
  i++
  const base = st.path
  const v = value(base.concat(names))
  if (!atEnd()) fail('trailing text after a value')
  assign(st.cur, base, names, v)
}

const cmp = (a, b) => {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let k = 0; k < Math.min(x.length, y.length); k++) if (x[k] !== y[k]) return x[k] - y[k]
  return x.length - y.length
}
const sortedKeys = (t) => [...t.m.keys()].sort(cmp)

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  if (n.t === 'table') {
    const ks = sortedKeys(n)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => pad + JSON.stringify(k) + ': ' + toJson(n.m.get(k), ind + 1)).join(',\n') + '\n' + end + '}'
  }
  if (n.t === 'array') {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((x) => pad + toJson(x, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  return JSON.stringify(n.v)
}

function keysOut(n, path, out) {
  if (n.t === 'table') {
    for (const k of sortedKeys(n)) {
      const p = path === null ? k : path + '.' + k
      out.push(p + ' ' + n.m.get(k).t)
      keysOut(n.m.get(k), p, out)
    }
  } else if (n.t === 'array') {
    n.items.forEach((x, k) => {
      const p = path + '[' + k + ']'
      out.push(p + ' ' + x.t)
      keysOut(x, p, out)
    })
  }
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}
const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()
const st = { root: newTable(), cur: null, path: [] }
st.cur = st.root
for (let k = 0; k < lines.length; k++) {
  const l = lines[k]
  try {
    parseLine(l, st)
  } catch (e) {
    if (!(e instanceof Fail)) throw e
    process.stderr.write(`error: line ${k + 1}: ${e.message}\n`)
    process.exit(2)
  }
}
if (args[0] === 'json') process.stdout.write(toJson(st.root, 0) + '\n')
else {
  const out = []
  keysOut(st.root, null, out)
  process.stdout.write(out.map((x) => x + '\n').join(''))
}
"}

